"""The movement library, loaded from data/movements.json (generated by scripts/build_movements.py)."""
from __future__ import annotations

import json
import unicodedata
from functools import lru_cache
from pathlib import Path

DATA = Path(__file__).resolve().parents[1] / "data"


def _fold(s: str) -> str:
    return "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c)).casefold()


class Catalog:
    def __init__(self, payload: dict):
        self.categories: list[dict] = payload["categories"]
        self.movements: list[dict] = payload["movements"]
        self._by_id = {m["id"]: m for m in self.movements}

    def get(self, movement_id: str) -> dict | None:
        return self._by_id.get(movement_id)

    def search(self, category: str | None = None, level: int | None = None, q: str = "") -> list[dict]:
        needle = _fold(q.strip())
        out = []
        for m in self.movements:
            if category and m["category"] != category:
                continue
            if level and m["level"] != level:
                continue
            if needle:
                hay = _fold(" ".join([m["name"], m["english"], *m.get("aka", [])]))
                if needle not in hay:
                    continue
            out.append(m)
        return out


@lru_cache(maxsize=1)
def load_catalog(path: str | None = None) -> Catalog:
    p = Path(path) if path else DATA / "movements.json"
    return Catalog(json.loads(p.read_text(encoding="utf-8")))
